/**
 * Shared Logger interface for all modules
 * Every module that produces output accepts Logger via constructor injection
 */

export interface Logger {
  success(msg: string): void;
  info(msg: string): void;
  warn(msg: string): void;
  error(msg: string, error?: Error): void;
  debug(msg: string): void;
}

/**
 * No-op logger that silences all output.
 * Used as default when no logger is injected — makes modules testable without console mocking.
 */
export function createNoopLogger(): Logger {
  return {
    success: () => {},
    info: () => {},
    warn: () => {},
    error: () => {},
    debug: () => {},
  };
}
