/**
 * Event delivery manager with Kafka primary, HTTP fallback, and retry logic
 */

import axios from 'axios';
import type { TestEvent } from '../types/index.js';
import type { KafkaEventProducer } from './kafka.js';
import type { HttpClient } from './http.js';
import type { Logger } from '../utils/logger.js';
import { createNoopLogger } from '../utils/logger.js';

export interface DeliveryManagerOptions {
  kafkaProducer?: KafkaEventProducer;
  httpClient: HttpClient;
  /** Absolute URL the server returned for HTTP fallback. Omit to disable HTTP delivery entirely. */
  httpFallbackUrl?: string;
  maxAttempts?: number;
  baseDelayMs?: number;
  /** Number of successful HTTP deliveries before attempting Kafka recovery probe */
  kafkaRecoveryThreshold?: number;
  /** Logger instance for output */
  logger?: Logger;
}

type DeliveryChannel = 'kafka' | 'http';

export class EventDeliveryManager {
  private readonly kafkaProducer: KafkaEventProducer | null;
  private readonly httpClient: HttpClient;
  private readonly httpFallbackUrl: string | null;
  private readonly maxAttempts: number;
  private readonly baseDelayMs: number;
  private readonly logger: Logger;

  private kafkaHealthy = true;
  private readonly kafkaRecoveryThreshold: number;
  private httpSuccessCount = 0;

  /** Timestamp of the last successful event delivery (Kafka or HTTP) */
  lastDeliveryAt = 0;

  constructor(options: DeliveryManagerOptions) {
    this.kafkaProducer = options.kafkaProducer ?? null;
    this.httpClient = options.httpClient;
    this.httpFallbackUrl = options.httpFallbackUrl ?? null;
    this.maxAttempts = options.maxAttempts ?? 3;
    this.baseDelayMs = options.baseDelayMs ?? 500;
    this.logger = options.logger ?? createNoopLogger();
    this.kafkaRecoveryThreshold = options.kafkaRecoveryThreshold ?? 3;
  }

  /**
   * Send a batch of events with retry and fallback.
   *
   * Strategy:
   * 1. If Kafka is healthy, try Kafka with reconnect-on-failure
   * 2. If Kafka fails after retries, mark unhealthy and fall back to HTTP
   * 3. If HTTP also fails, throw (buffer will restore events for next flush)
   */
  async sendBatch(events: TestEvent[]): Promise<void> {
    if (events.length === 0) return;

    // Skip Kafka if no producer configured (HTTP-only mode)
    if (this.kafkaProducer && this.kafkaHealthy) {
      const kafkaSuccess = await this.tryKafkaWithRetry(events);
      if (kafkaSuccess) {
        this.lastDeliveryAt = Date.now();
        return;
      }

      // Kafka exhausted — mark unhealthy so future calls skip straight to HTTP
      this.kafkaHealthy = false;
      this.logger.warn('Kafka failed — switching to HTTP fallback');
    }

    // HTTP fallback
    await this.tryHttpWithRetry(events);
  }

  /**
   * Send a single event (used for run:end which must be sent directly)
   */
  async send(event: TestEvent): Promise<void> {
    await this.sendBatch([event]);
  }

  /**
   * Try sending via Kafka with reconnect attempts.
   * Returns true if delivery succeeded, false if all attempts exhausted.
   */
  private async tryKafkaWithRetry(events: TestEvent[]): Promise<boolean> {
    if (!this.kafkaProducer) return false;

    for (let attempt = 1; attempt <= this.maxAttempts; attempt++) {
      try {
        // If disconnected (after a prior failure), try to reconnect
        if (!this.kafkaProducer.isConnected) {
          this.logger.debug(`Kafka reconnect attempt ${attempt}/${this.maxAttempts}`);
          await this.kafkaProducer.connect();
        }

        await this.kafkaProducer.sendBatch(events);

        const first = events[0];
        const last = events[events.length - 1];
        const seqRange = 'sequence' in first ? `(seq ${first.sequence}-${(last as typeof first).sequence})` : '';
        this.logger.debug(`Flushed ${events.length} events via kafka ${seqRange}`.trim());
        return true;
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);

        if (attempt < this.maxAttempts) {
          const delay = this.getBackoffDelay(attempt);
          this.logger.debug(
            `Kafka send failed: ${message} (attempt ${attempt}/${this.maxAttempts}, retrying in ${delay}ms)`
          );
          await this.sleep(delay);
        } else {
          this.logger.error(`Kafka delivery failed after ${this.maxAttempts} attempts: ${message}`);
        }
      }
    }

    return false;
  }

  /**
   * Try sending via HTTP with retry.
   * Throws if all attempts fail (buffer will restore events).
   */
  private async tryHttpWithRetry(events: TestEvent[]): Promise<void> {
    if (!this.httpFallbackUrl) {
      throw new Error('HTTP fallback not configured — server did not return httpFallback URL');
    }

    const fallbackUrl = this.httpFallbackUrl;
    let lastError: Error | undefined;

    for (let attempt = 1; attempt <= this.maxAttempts; attempt++) {
      try {
        await this.httpClient.sendEvents(fallbackUrl, events);

        const first = events[0];
        const last = events[events.length - 1];
        const seqRange = 'sequence' in first ? `(seq ${first.sequence}-${(last as typeof first).sequence})` : '';
        this.logger.debug(`Flushed ${events.length} events via http ${seqRange}`.trim());
        this.lastDeliveryAt = Date.now();

        // Track HTTP successes and probe Kafka recovery when threshold is reached
        if (!this.kafkaHealthy) {
          this.httpSuccessCount++;
          if (this.httpSuccessCount >= this.kafkaRecoveryThreshold) {
            this.logger.debug(
              `HTTP success ${this.kafkaRecoveryThreshold}/${this.kafkaRecoveryThreshold} — probing Kafka recovery`
            );
            this.tryKafkaRecovery().catch(() => {});
          }
        }
        return;
      } catch (error) {
        // Permanent errors — don't retry, same payload will fail again
        if (axios.isAxiosError(error) && error.response?.status === 413) {
          this.logger.error('HTTP batch too large (413) — events discarded');
          throw error;
        }
        if (axios.isAxiosError(error) && error.response?.status === 401) {
          this.logger.error('HTTP fallback auth failed (401) — check API key');
          throw error;
        }

        lastError = error instanceof Error ? error : new Error(String(error));
        const message = lastError.message;

        if (attempt < this.maxAttempts) {
          const delay = this.getBackoffDelay(attempt);
          this.logger.debug(`HTTP attempt ${attempt}/${this.maxAttempts} failed: ${message} (retrying in ${delay}ms)`);
          await this.sleep(delay);
        } else {
          this.logger.error(`HTTP fallback delivery failed after ${this.maxAttempts} attempts: ${message}`);
        }
      }
    }

    throw lastError ?? new Error('HTTP fallback delivery failed — no attempts made (maxAttempts must be >= 1)');
  }

  /**
   * Attempt to reconnect to Kafka after sustained HTTP success.
   * Resets counter regardless of outcome to avoid constant re-probing.
   */
  private async tryKafkaRecovery(): Promise<void> {
    if (!this.kafkaProducer) return;

    this.httpSuccessCount = 0;
    try {
      await this.kafkaProducer.connect();
      this.kafkaHealthy = true;
      this.logger.debug('Kafka connection recovered — resuming primary channel');
    } catch {
      this.logger.debug('Kafka recovery failed — staying on HTTP');
    }
  }

  /** Exponential backoff: baseDelay * 2^(attempt-1) */
  private getBackoffDelay(attempt: number): number {
    return this.baseDelayMs * Math.pow(2, attempt - 1);
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /** Current delivery channel preference */
  get activeChannel(): DeliveryChannel {
    if (!this.kafkaProducer) return 'http';
    return this.kafkaHealthy ? 'kafka' : 'http';
  }
}
